// Hypothesis: output row for column j spans rows 0..last(j), where last(j) is the
// last input row whose length > j. Missing cells become ' '.
function transposeH(rows) {
  if (!rows.length) return [];
  const maxLen = Math.max(...rows.map(r => r.length));
  const out = [];
  for (let j = 0; j < maxLen; j++) {
    let last = -1;
    for (let i = 0; i < rows.length; i++) if (rows[i].length > j) last = i;
    let s = '';
    for (let i = 0; i <= last; i++) s += j < rows[i].length ? rows[i][j] : ' ';
    out.push(s);
  }
  return out;
}

const cases = {
  'two chars row': { in: ['A1'], ex: ['A','1'] },
  'two chars col': { in: ['A','1'], ex: ['A1'] },
  'simple': { in: ['ABC','123'], ex: ['A1','B2','C3'] },
  'single line': { in: ['Single line.'], ex: ['S','i','n','g','l','e',' ','l','i','n','e','.'] },
  'first longer': { in: ['The fourth line.','The fifth line.'], ex: ['TT','hh','ee','  ','ff','oi','uf','rt','th','h ',' l','li','in','ne','e.','.'] },
  'second longer': { in: ['The first line.','The second line.'], ex: ['TT','hh','ee','  ','fs','ie','rc','so','tn',' d','l ','il','ni','en','.e',' .'] },
  'mixed': { in: ['The longest line.','A long line.','A longer line.','A line.'], ex: ['TAAA','h   ','elll',' ooi','lnnn','ogge','n e.','glr','ei ','snl','tei',' .n','l e','i .','n','e','.'] },
  'square': { in: ['HEART','EMBER','ABUSE','RESIN','TREND'], ex: ['HEART','EMBER','ABUSE','RESIN','TREND'] },
  'rectangle': { in: ['FRACTURE','OUTLINED','BLOOMING','SEPTETTE'], ex: ['FOBS','RULE','ATOP','CLOT','TIME','UNIT','RENT','EDGE'] },
  'triangle': { in: ['T','EE','AAA','SSSS','EEEEE','RRRRRR'], ex: ['TEASER',' EASER','  ASER','   SER','    ER','     R'] },
  'jagged triangle': { in: ['11','2','3333','444','555555','66666'], ex: ['123456','1 3456','  3456','  3 56','    56','    5'] },
};

let allPass = true;
for (const [name, {in: inp, ex}] of Object.entries(cases)) {
  const got = transposeH(inp);
  const ok = JSON.stringify(got) === JSON.stringify(ex);
  if (!ok) {
    allPass = false;
    console.log(`FAIL ${name}`);
    for (let i = 0; i < Math.max(got.length, ex.length); i++) {
      if (got[i] !== ex[i]) console.log(`  col ${i}: got ${JSON.stringify(got[i])}  exp ${JSON.stringify(ex[i])}`);
    }
  } else console.log(`ok   ${name}`);
}
console.log(allPass ? 'ALL PASS' : 'SOME FAIL');
EOF
